import React, { use } from "react";

import styles from"./styles/UserRegistry.module.css";

export default function UserRegistry() {
    const [users, setUsers] = useState(null);

    useEffect(() => {
        async function fetchUsers() {
            try {
                const response = await fetch("http://localhost:3001/getusers");

                 const data = await response.json();

                if (!response.ok) {
                    alert('Sikertelen lekérdezés: ${data.message}');
                } else {
                    setGames(data.games);
                }
            } catch (err) {
                console.log(err);
                alert("Hiba történt a játékok lekérése közben.");
            }
        }
        fetchUsers();
    }, []);
    
   return (
    <table className={styles.registry_table}>
      <tbody>
        {users ? (users.map(user => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.email}</td>
              <td>3 of 3</td>
            </tr>
          ))
        ) : (
          <tr>
            <td colSpan="3">Betöltés...</td>
          </tr>
        )}
      </tbody>
    </table>
  );
}
